<?php
require_once "config/db.php";$pageTitle='Trainers';
if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='add'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$specialty=trim($_POST['specialty']??'');$salary=$_POST['salary']??0;if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9]{10,15}$/',$phone)||!is_numeric($salary)||$salary<0){$_SESSION['flash']=['type'=>'error','message'=>'Enter valid trainer details.'];}else{$st=$pdo->prepare("INSERT INTO trainers(name,email,phone,specialty,salary) VALUES(?,?,?,?,?)");$st->execute([$name,$email,$phone,$specialty,$salary]);$_SESSION['flash']=['type'=>'success','message'=>'Trainer added.'];}}elseif(($_POST['action']??'')==='delete'){$st=$pdo->prepare("DELETE FROM trainers WHERE id=?");$st->execute([(int)$_POST['id']]);$_SESSION['flash']=['type'=>'success','message'=>'Trainer deleted.'];}header("Location: trainers.php");exit;}
$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT * FROM trainers WHERE name LIKE ? OR email LIKE ? OR specialty LIKE ? ORDER BY id DESC");$st->execute(["%$q%","%$q%","%$q%"]);$trainers=$st->fetchAll();require "includes/header.php";
?><div class="page-intro"><div><h1>Trainer management</h1><p>Manage your coaching team and their specialities.</p></div></div><section class="panel"><div class="panel-head"><div><h3>Add trainer</h3><p>Enter contact and professional details.</p></div></div><form method="post" class="form-grid" data-validate><input type="hidden" name="action" value="add"><div class="field"><label>Full name *</label><input name="name" required minlength="2"></div><div class="field"><label>Email *</label><input name="email" type="email" required></div><div class="field"><label>Phone *</label><input name="phone" pattern="[0-9]{10,15}" required></div><div class="field"><label>Specialty</label><input name="specialty" placeholder="Strength training"></div><div class="field"><label>Monthly salary (₹)</label><input name="salary" type="number" min="0" step=".01" value="0" required></div><div class="field field-action"><button class="btn btn-primary">＋ Add trainer</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Your coaching team <span class="count"><?= count($trainers) ?></span></h3></div><form class="inline-search"><input name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Search trainers"><button class="btn btn-secondary">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>TRAINER</th><th>PHONE</th><th>SPECIALTY</th><th>MONTHLY SALARY</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($trainers as $t): ?><tr><td><div class="person"><span class="table-avatar"><?= strtoupper(substr($t['name'],0,1)) ?></span><span><b><?= htmlspecialchars($t['name']) ?></b><small><?= htmlspecialchars($t['email']) ?></small></span></div></td><td><?= htmlspecialchars($t['phone']) ?></td><td><?= htmlspecialchars($t['specialty']) ?></td><td>₹<?= number_format($t['salary'],2) ?></td><td><form method="post" onsubmit="return confirm('Delete this trainer?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $t['id'] ?>"><button class="delete-link">Delete</button></form></td></tr><?php endforeach; if(!$trainers): ?><tr><td colspan="5" class="empty">No trainers found.</td></tr><?php endif; ?></tbody></table></div></section><?php require "includes/footer.php"; ?>